const INDEX_HTML = "<!doctype html>\n<html lang=\"zh-CN\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <meta name=\"theme-color\" content=\"#0b0d10\" />\n  <meta name=\"description\" content=\"一个为视频创作者准备的轻量从夯到拉分档看板。\" />\n  <title>夯拉板</title>\n  <link rel=\"icon\" type=\"image/svg+xml\" href=\"data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 64 64'%3E%3Crect width='64' height='64' rx='14' fill='%230b0d10'/%3E%3Cpath d='M14 16h36v9H14zm0 13h28v9H14zm0 13h20v9H14z' fill='%23f3ff63'/%3E%3C/svg%3E\" />\n  <style>\n    :root {\n      color-scheme: dark;\n      --bg: #0b0d10;\n      --panel: #12151a;\n      --panel-2: #171b21;\n      --line: #2a3039;\n      --text: #f5f6f7;\n      --muted: #9aa3ae;\n      --accent: #eaff5b;\n      --accent-ink: #151800;\n      --danger: #ff6d68;\n      --tile: 92px;\n    }\n\n    * { box-sizing: border-box; }\n    [hidden] { display: none !important; }\n\n    html, body { margin: 0; min-height: 100%; background: var(--bg); color: var(--text); }\n\n    body {\n      font-family: Inter, ui-sans-serif, -apple-system, BlinkMacSystemFont, \"Segoe UI\", \"PingFang SC\", \"Microsoft YaHei\", sans-serif;\n      overflow-x: hidden;\n    }\n\n    button, input { font: inherit; }\n\n    button {\n      border: 1px solid var(--line);\n      border-radius: 10px;\n      background: var(--panel-2);\n      color: var(--text);\n      min-height: 42px;\n      padding: 0 15px;\n      cursor: pointer;\n      transition: transform .16s ease, border-color .16s ease, background .16s ease;\n    }\n\n    button:hover { border-color: #4b5563; background: #20252d; }\n    button:active { transform: translateY(1px); }\n    button:disabled { cursor: wait; opacity: .58; transform: none; }\n    button:focus-visible, input:focus-visible { outline: 3px solid rgba(234,255,91,.38); outline-offset: 2px; }\n\n    .primary { background: var(--accent); color: var(--accent-ink); border-color: var(--accent); font-weight: 800; }\n    .primary:hover { background: #f1ff91; border-color: #f1ff91; }\n\n    .app-shell { min-height: 100vh; display: flex; flex-direction: column; }\n\n    .topbar {\n      min-height: 76px;\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      gap: 20px;\n      padding: 14px 24px;\n      border-bottom: 1px solid var(--line);\n      background: rgba(11,13,16,.94);\n      position: sticky;\n      top: 0;\n      z-index: 20;\n      backdrop-filter: blur(16px);\n    }\n\n    .brand { display: flex; align-items: center; gap: 13px; min-width: 190px; }\n    .brand-mark { width: 42px; height: 42px; border-radius: 11px; background: var(--accent); color: var(--accent-ink); display: grid; place-items: center; font-size: 24px; font-weight: 1000; transform: rotate(-3deg); }\n    .brand h1 { margin: 0; font-size: 1.08rem; letter-spacing: .01em; }\n    .brand span { display: block; margin-top: 2px; color: var(--muted); font-size: .78rem; }\n\n    .actions { display: flex; gap: 9px; flex-wrap: wrap; justify-content: flex-end; }\n    .button-icon { display: inline-block; margin-right: 7px; font-weight: 900; }\n    .theme-control { min-height: 42px; display: flex; align-items: center; gap: 9px; padding: 0 11px 0 13px; border: 1px solid var(--line); border-radius: 10px; background: var(--panel-2); color: var(--muted); font-size: .88rem; }\n    .theme-control select { border: 0; background: transparent; color: var(--text); font: inherit; font-weight: 700; cursor: pointer; }\n    .theme-control select:focus { outline: 0; }\n\n    .room-bar { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 10px 24px; border-bottom: 1px solid #294534; background: #101b15; color: #dfffea; }\n    .room-info, .room-actions, .room-people { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }\n    .online-dot { width: 9px; height: 9px; border-radius: 50%; background: #63e08b; box-shadow: 0 0 0 4px rgba(99,224,139,.12); }\n    .room-code { color: #fff; font-weight: 900; letter-spacing: .12em; }\n    .room-people { color: #a9c5b3; font-size: .88rem; }\n    .room-bar button { min-height: 34px; padding: 0 11px; border-color: #31553e; background: #17271d; }\n    .room-bar .finalize { color: #10180d; border-color: #9ee874; background: #9ee874; font-weight: 800; }\n    .room-final-label { display: none; padding: 5px 10px; border-radius: 99px; color: #171400; background: #f4dc66; font-size: .82rem; font-weight: 900; }\n    body.room-finalized .room-final-label { display: inline-flex; }\n    body.room-finalized .tier-drop, body.room-finalized .asset-bank, body.room-finalized .tier-tools { pointer-events: none; opacity: .78; }\n\n    .room-modal { position: fixed; inset: 0; z-index: 150; display: none; place-items: center; padding: 20px; background: rgba(4,6,8,.78); backdrop-filter: blur(10px); }\n    .room-modal.open { display: grid; }\n    .room-dialog { width: min(520px, 100%); border: 1px solid #343c47; border-radius: 18px; background: #12161b; box-shadow: 0 28px 100px rgba(0,0,0,.55); overflow: hidden; }\n    .room-dialog-header { display: flex; align-items: flex-start; justify-content: space-between; gap: 20px; padding: 22px 22px 14px; }\n    .room-dialog h2 { margin: 0 0 6px; font-size: 1.35rem; }\n    .room-dialog p { margin: 0; color: var(--muted); line-height: 1.55; font-size: .9rem; }\n    .room-close { width: 36px; height: 36px; min-height: 36px; padding: 0; border: 0; background: transparent; font-size: 1.4rem; }\n    .room-form { display: grid; gap: 14px; padding: 8px 22px 24px; }\n    .room-field { display: grid; gap: 7px; }\n    .room-field label { color: #cdd3da; font-size: .86rem; font-weight: 700; }\n    .room-field input, .room-field select { width: 100%; min-height: 46px; padding: 0 13px; border: 1px solid #343c47; border-radius: 10px; background: #0d1014; color: var(--text); font-size: 1rem; }\n    .room-field input.room-number { text-align: center; font-size: 1.3rem; font-weight: 900; letter-spacing: .2em; }\n    .room-choice { display: grid; grid-template-columns: 1fr auto 1fr; align-items: end; gap: 13px; }\n    .room-or { align-self: center; color: #68717d; font-size: .78rem; }\n    .room-submit { width: 100%; }\n    .room-note { padding-top: 3px; color: #7f8995 !important; font-size: .8rem !important; }\n    .host-exit-actions { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }\n    .danger-action { border-color: #773b3b; color: #ffd2d0; background: #361b1b; }\n\n    .workspace { width: min(1500px, 100%); margin: 0 auto; padding: 24px; flex: 1; }\n\n    .board-header { display: flex; align-items: end; justify-content: space-between; gap: 20px; margin-bottom: 14px; }\n    .board-title { display: block; width: min(720px, 80vw); margin: 0 0 6px; padding: 2px 0 5px; border: 0; border-bottom: 2px solid transparent; background: transparent; color: var(--text); font-size: clamp(1.35rem, 2vw, 2rem); line-height: 1.1; font-weight: 800; }\n    .board-title:hover { border-bottom-color: var(--line); }\n    .board-title:focus { border-bottom-color: var(--accent); outline: 0; }\n    .board-title::placeholder { color: #6f7782; }\n    .board-header p { color: var(--muted); margin: 0; font-size: .9rem; }\n\n    .board {\n      overflow: hidden;\n      border: 1px solid var(--line);\n      border-radius: 14px;\n      background: var(--panel);\n      box-shadow: 0 24px 80px rgba(0,0,0,.26);\n    }\n\n    .tier {\n      display: grid;\n      grid-template-columns: 148px minmax(0, 1fr) 92px;\n      min-height: 116px;\n      border-bottom: 1px solid var(--line);\n    }\n    .tier:last-child { border-bottom: 0; }\n\n    .tier-name {\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      padding: 13px;\n      background: var(--tier-color);\n    }\n\n    .tier-name input {\n      width: 100%;\n      border: 0;\n      border-bottom: 2px solid transparent;\n      background: transparent;\n      color: #151515;\n      text-align: center;\n      font-size: 1rem;\n      font-weight: 1000;\n      padding: 8px 2px;\n    }\n    .tier-name input:hover, .tier-name input:focus { border-bottom-color: rgba(0,0,0,.28); outline: 0; }\n\n    .tier-drop {\n      display: flex;\n      flex-wrap: wrap;\n      align-content: flex-start;\n      gap: 8px;\n      min-width: 0;\n      padding: 11px;\n      background-image: linear-gradient(90deg, rgba(255,255,255,.012) 1px, transparent 1px), linear-gradient(rgba(255,255,255,.012) 1px, transparent 1px);\n      background-size: 20px 20px;\n    }\n\n    .tier-drop.drag-over, .asset-bank.drag-over { background-color: rgba(234,255,91,.08); box-shadow: inset 0 0 0 2px var(--accent); }\n\n    .tier-tools { display: flex; align-items: center; justify-content: center; gap: 2px; padding: 4px; border-left: 1px solid var(--line); }\n    .drag-tier { width: 36px; height: 36px; min-height: 36px; padding: 0; color: var(--muted); border: 0; background: transparent; font-size: 1.2rem; cursor: grab; letter-spacing: -4px; }\n    .drag-tier:hover { color: var(--accent); background: rgba(234,255,91,.08); }\n    .drag-tier:active { cursor: grabbing; }\n    .delete-tier { width: 36px; height: 36px; min-height: 36px; padding: 0; color: var(--muted); border: 0; background: transparent; font-size: 1.25rem; }\n    .delete-tier:hover { color: var(--danger); background: rgba(255,109,104,.1); }\n    .tier.tier-drag-before { box-shadow: inset 0 4px 0 var(--accent); }\n    .tier.tier-drag-after { box-shadow: inset 0 -4px 0 var(--accent); }\n\n    .tile {\n      position: relative;\n      width: var(--tile);\n      height: var(--tile);\n      border-radius: 9px;\n      overflow: hidden;\n      border: 2px solid rgba(255,255,255,.13);\n      background: #252a32;\n      cursor: grab;\n      box-shadow: 0 6px 14px rgba(0,0,0,.24);\n      user-select: none;\n    }\n    .tile:active { cursor: grabbing; }\n    .tile.dragging { opacity: .35; }\n    .tile img { width: 100%; height: 100%; display: block; object-fit: cover; pointer-events: none; }\n    .tile button { position: absolute; top: 4px; right: 4px; width: 25px; height: 25px; min-height: 25px; padding: 0; border: 0; border-radius: 50%; background: rgba(6,7,9,.82); opacity: 0; }\n    .tile:hover button, .tile button:focus { opacity: 1; }\n\n    .bank-section { margin-top: 18px; border: 1px solid var(--line); border-radius: 14px; background: var(--panel); overflow: hidden; }\n    .bank-header { min-height: 58px; display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 9px 14px 9px 18px; border-bottom: 1px solid var(--line); }\n    .bank-title { display: flex; align-items: baseline; gap: 10px; }\n    .bank-title h3 { margin: 0; font-size: 1rem; }\n    .count { color: var(--muted); font-size: .8rem; }\n\n    .asset-bank { min-height: 132px; display: flex; flex-wrap: wrap; align-content: flex-start; gap: 9px; padding: 14px; }\n    .empty { width: 100%; min-height: 102px; display: grid; place-items: center; color: var(--muted); text-align: center; border: 1px dashed #343b45; border-radius: 10px; font-size: .9rem; line-height: 1.7; padding: 20px; }\n\n    #fileInput { position: absolute; opacity: 0; width: 1px; height: 1px; pointer-events: none; }\n\n    .drop-mask { position: fixed; inset: 0; z-index: 100; display: none; place-items: center; background: rgba(5,7,9,.82); backdrop-filter: blur(8px); }\n    .drop-mask.visible { display: grid; }\n    .drop-card { border: 2px dashed var(--accent); border-radius: 22px; padding: 55px 80px; color: var(--accent); font-size: 1.25rem; font-weight: 800; background: rgba(234,255,91,.06); }\n\n    .toast { position: fixed; left: 50%; bottom: 24px; z-index: 120; transform: translate(-50%, 20px); opacity: 0; pointer-events: none; padding: 11px 17px; border-radius: 99px; background: #f3f5f7; color: #16191d; font-weight: 700; transition: .2s ease; }\n    .toast.show { opacity: 1; transform: translate(-50%, 0); }\n\n    .recording-badge { display: none; }\n\n    body.recording { background: #000; }\n    body.recording .topbar, body.recording .room-bar, body.recording .board-header, body.recording .tier-tools, body.recording .bank-header { display: none; }\n    body.recording .workspace { width: 100%; height: 100vh; padding: 0; margin: 0; display: grid; grid-template-rows: minmax(0, 1fr) 132px; overflow: hidden; }\n    body.recording .board { border: 0; border-radius: 0; min-height: 0; height: 100%; box-shadow: none; overflow: hidden; }\n    body.recording .tier { grid-template-columns: clamp(115px, 13vw, 210px) minmax(0, 1fr); min-height: calc((100vh - 132px) / var(--tier-count)); height: calc((100vh - 132px) / var(--tier-count)); }\n    body.recording .tier-name input { font-size: clamp(1rem, 2vw, 1.75rem); pointer-events: none; }\n    body.recording .tier-drop { padding: 10px; align-content: center; background-image: none; }\n    body.recording .tile { width: min(clamp(68px, 7.8vw, 122px), calc((100vh - 154px) / var(--tier-count))); height: min(clamp(68px, 7.8vw, 122px), calc((100vh - 154px) / var(--tier-count))); flex: 0 0 auto; }\n    body.recording .tile button { display: none; }\n    body.recording .bank-section { display: block; height: 132px; min-height: 132px; margin: 0; border: 0; border-top: 2px solid rgba(234,255,91,.72); border-radius: 0; background: #090b0e; overflow: hidden; }\n    body.recording .asset-bank { height: 130px; min-height: 130px; flex-wrap: nowrap; align-items: center; align-content: center; overflow-x: auto; overflow-y: hidden; padding: 14px 18px; background: linear-gradient(90deg, rgba(234,255,91,.035), transparent 45%); }\n    body.recording .asset-bank .empty { min-width: 100%; min-height: 96px; border-color: rgba(255,255,255,.12); }\n    body.recording .recording-badge { display: block; position: fixed; right: 16px; bottom: 14px; z-index: 40; color: rgba(255,255,255,.42); font-size: 12px; letter-spacing: .08em; opacity: 0; transition: opacity .2s ease; }\n    body.recording:hover .recording-badge { opacity: 1; }\n\n    @media (max-width: 760px) {\n      :root { --tile: 74px; }\n      .topbar { align-items: flex-start; padding: 12px 14px; }\n      .brand span { display: none; }\n      .brand { min-width: 0; }\n      .brand-mark { width: 38px; height: 38px; }\n      .actions button { padding: 0 11px; }\n      .actions .button-label { display: none; }\n      .button-icon { margin-right: 0; }\n      .workspace { padding: 14px; }\n      .tier { grid-template-columns: 96px minmax(0, 1fr) 78px; min-height: 100px; }\n      .tier-name { padding: 6px; }\n      .tier-name input { font-size: .88rem; }\n      .board-header { align-items: flex-start; }\n      .board-header p { max-width: 28ch; }\n      .room-bar { align-items: flex-start; padding: 10px 14px; }\n      .room-people { display: none; }\n      .room-choice { grid-template-columns: 1fr; }\n      .room-or { text-align: center; }\n    }\n\n    @media (prefers-reduced-motion: reduce) {\n      *, *::before, *::after { scroll-behavior: auto !important; transition: none !important; }\n    }\n  </style>\n</head>\n<body>\n  <div class=\"app-shell\">\n    <header class=\"topbar\">\n      <div class=\"brand\">\n        <div class=\"brand-mark\" aria-hidden=\"true\">夯</div>\n        <div><h1>夯拉板</h1><span>视频创作者分档工具</span></div>\n      </div>\n      <div class=\"actions\" aria-label=\"看板操作\">\n        <label class=\"theme-control\"><span>主题</span><select id=\"themeSelect\" aria-label=\"档位颜色主题\"><option value=\"rainbow\">彩虹色</option><option value=\"ember\">红橙黄白</option></select></label>\n        <button id=\"addTierBtn\" type=\"button\" title=\"增加一个档位\"><span class=\"button-icon\">＋</span><span class=\"button-label\">加一档</span></button>\n        <button id=\"uploadBtn\" type=\"button\" class=\"primary\" title=\"批量上传图片\"><span class=\"button-icon\">↑</span><span class=\"button-label\">上传图片</span></button>\n        <button id=\"roomBtn\" type=\"button\" title=\"创建或加入联机房间\"><span class=\"button-icon\">◎</span><span class=\"button-label\">联机房间</span></button>\n        <button id=\"exportBtn\" type=\"button\" title=\"将当前分档结果导出为 PNG 图片\"><span class=\"button-icon\">⇩</span><span class=\"button-label\">导出图片</span></button>\n        <button id=\"recordBtn\" type=\"button\" title=\"隐藏控件并进入全屏\"><span class=\"button-icon\">●</span><span class=\"button-label\">干净录制</span></button>\n      </div>\n    </header>\n\n    <section id=\"roomBar\" class=\"room-bar\" aria-label=\"联机房间状态\" hidden>\n      <div class=\"room-info\"><span class=\"online-dot\" aria-hidden=\"true\"></span><span>房间 <strong id=\"roomCode\" class=\"room-code\">A1B2C3D4</strong></span><span id=\"roomFinalLabel\" class=\"room-final-label\">已定稿</span></div>\n      <div id=\"roomPeople\" class=\"room-people\">1 人在线</div>\n      <div class=\"room-actions\"><button id=\"copyRoomBtn\" type=\"button\">复制邀请</button><button id=\"finalizeBtn\" class=\"finalize\" type=\"button\" hidden>锁定最终排名</button><button id=\"leaveRoomBtn\" type=\"button\">退出房间</button></div>\n    </section>\n\n    <main class=\"workspace\">\n      <div class=\"board-header\">\n        <div><input id=\"boardTitle\" class=\"board-title\" type=\"text\" value=\"这期怎么排？\" maxlength=\"80\" aria-label=\"排序标题\" title=\"点击修改排序标题\"><p>点击标题可以改名；拖动图片进档位，点击档名可以直接修改。</p></div>\n      </div>\n      <section id=\"board\" class=\"board\" aria-label=\"分档看板\"></section>\n\n      <section class=\"bank-section\" aria-label=\"待分档图片\">\n        <div class=\"bank-header\">\n          <div class=\"bank-title\"><h3>待分档</h3><span id=\"itemCount\" class=\"count\">0 张</span></div>\n          <button id=\"bankUploadBtn\" type=\"button\">＋ 添加图片</button>\n        </div>\n        <div id=\"assetBank\" class=\"asset-bank\" data-zone=\"bank\"></div>\n      </section>\n    </main>\n  </div>\n\n  <input id=\"fileInput\" type=\"file\" accept=\"image/png,image/jpeg,image/webp,image/gif\" multiple />\n  <div id=\"dropMask\" class=\"drop-mask\" aria-hidden=\"true\"><div class=\"drop-card\">松手即可添加图片</div></div>\n  <div class=\"recording-badge\">按 ESC 退出录制模式</div>\n  <div id=\"toast\" class=\"toast\" role=\"status\" aria-live=\"polite\"></div>\n\n  <div id=\"roomModal\" class=\"room-modal\" aria-hidden=\"true\">\n    <section class=\"room-dialog\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"roomDialogTitle\">\n      <div class=\"room-dialog-header\">\n        <div><h2 id=\"roomDialogTitle\">联机一起排</h2><p>创建房间后，把房间号或邀请链接发给连线嘉宾。</p></div>\n        <button id=\"roomCloseBtn\" class=\"room-close\" type=\"button\" aria-label=\"关闭\">×</button>\n      </div>\n      <div class=\"room-form\">\n        <div class=\"room-field\"><label for=\"nicknameInput\">你的昵称</label><input id=\"nicknameInput\" type=\"text\" maxlength=\"24\" placeholder=\"例如：主持人\"></div>\n        <div class=\"room-choice\">\n          <button id=\"createRoomBtn\" class=\"primary room-submit\" type=\"button\">创建新房间</button>\n          <span class=\"room-or\">或者</span>\n          <div class=\"room-field\"><label for=\"joinCodeInput\">输入 8 位房间号</label><input id=\"joinCodeInput\" class=\"room-number\" type=\"text\" inputmode=\"text\" maxlength=\"8\" autocomplete=\"one-time-code\" autocapitalize=\"characters\" spellcheck=\"false\" placeholder=\"A1B2C3D4\"><button id=\"joinRoomBtn\" class=\"room-submit\" type=\"button\">加入房间</button></div>\n        </div>\n        <p class=\"room-note\">联机后，标题、主题、档位和图片调整会同步给房间内所有人。房主定稿后将暂停编辑。</p>\n      </div>\n    </section>\n  </div>\n\n  <div id=\"hostExitModal\" class=\"room-modal\" aria-hidden=\"true\">\n    <section class=\"room-dialog\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"hostExitTitle\">\n      <div class=\"room-dialog-header\">\n        <div><h2 id=\"hostExitTitle\">交接或解散房间</h2><p>房主不能直接退出。你可以转让给其他参与者，或者解散整个房间。</p></div>\n        <button id=\"hostExitCloseBtn\" class=\"room-close\" type=\"button\" aria-label=\"关闭\">×</button>\n      </div>\n      <div class=\"room-form\">\n        <div id=\"transferField\" class=\"room-field\"><label for=\"transferTargetSelect\">转让给</label><select id=\"transferTargetSelect\"></select></div>\n        <div class=\"host-exit-actions\">\n          <button id=\"transferRoomBtn\" class=\"primary\" type=\"button\">转让并退出</button>\n          <button id=\"dissolveRoomBtn\" class=\"danger-action\" type=\"button\">解散房间</button>\n        </div>\n        <p id=\"hostExitNote\" class=\"room-note\">解散后，所有参与者都会离开，房间链接立即失效。</p>\n      </div>\n    </section>\n  </div>\n\n  <script>\n    (() => {\n      const THEMES = {\n        rainbow: ['#f05b56', '#f09b53', '#f2d35d', '#8ecb67', '#62b9d8', '#8d7bd8', '#d27ac0'],\n        ember: ['#ef4444', '#f97316', '#facc15', '#fde68a', '#f8fafc']\n      };\n      const state = {\n        title: '这期怎么排？',\n        theme: 'rainbow',\n        tiers: [\n          { id: crypto.randomUUID(), name: '夯', items: [] },\n          { id: crypto.randomUUID(), name: '顶级', items: [] },\n          { id: crypto.randomUUID(), name: '人上人', items: [] },\n          { id: crypto.randomUUID(), name: 'NPC', items: [] },\n          { id: crypto.randomUUID(), name: '拉完了', items: [] }\n        ],\n        bank: [],\n        items: new Map(),\n        draggingId: null,\n        draggingTierId: null,\n        applyingRemote: false,\n        room: null\n      };\n\n      const board = document.querySelector('#board');\n      const bank = document.querySelector('#assetBank');\n      const fileInput = document.querySelector('#fileInput');\n      const itemCount = document.querySelector('#itemCount');\n      const dropMask = document.querySelector('#dropMask');\n      const toast = document.querySelector('#toast');\n      const roomModal = document.querySelector('#roomModal');\n      const roomBar = document.querySelector('#roomBar');\n      const hostExitModal = document.querySelector('#hostExitModal');\n      let toastTimer;\n      let externalDragDepth = 0;\n      let roomSyncTimer;\n      let roomPollTimer;\n      let roomPresenceTimer;\n      let syncInFlight = false;\n      let syncQueued = false;\n      let hostClaimInFlight = false;\n\n      function say(message) {\n        toast.textContent = message;\n        toast.classList.add('show');\n        clearTimeout(toastTimer);\n        toastTimer = setTimeout(() => toast.classList.remove('show'), 1800);\n      }\n\n      function canEdit() {\n        if (!state.room?.finalized) return true;\n        say('最终排名已锁定，请让房主先解锁');\n        return false;\n      }\n\n      function serializeBoard(emptyItems = false) {\n        return {\n          title: state.title,\n          theme: state.theme,\n          tiers: state.tiers.map(tier => ({ ...tier, items: emptyItems ? [] : [...tier.items] })),\n          bank: emptyItems ? [] : [...state.bank],\n          items: emptyItems ? [] : [...state.items.values()].map(item => ({\n            id: item.id,\n            name: item.name,\n            url: item.url,\n            remoteId: item.remoteId || null\n          }))\n        };\n      }\n\n      function applyRemoteBoard(nextState) {\n        if (!nextState) return;\n        state.applyingRemote = true;\n        state.items.forEach(item => {\n          if (item.url?.startsWith('blob:')) URL.revokeObjectURL(item.url);\n        });\n        state.title = String(nextState.title || '这期怎么排？');\n        state.theme = THEMES[nextState.theme] ? nextState.theme : 'rainbow';\n        state.tiers = Array.isArray(nextState.tiers) ? nextState.tiers.map(tier => ({\n          id: tier.id,\n          name: tier.name,\n          items: [...tier.items]\n        })) : [];\n        state.bank = Array.isArray(nextState.bank) ? [...nextState.bank] : [];\n        state.items = new Map((nextState.items || []).map(item => [item.id, { ...item }]));\n        document.querySelector('#boardTitle').value = state.title;\n        document.querySelector('#themeSelect').value = state.theme;\n        render();\n        state.applyingRemote = false;\n      }\n\n      async function requestJson(url, options = {}) {\n        let response;\n        for (let attempt = 0; attempt < 2; attempt += 1) {\n          try {\n            response = await fetch(url, options);\n            break;\n          } catch (error) {\n            if (attempt === 1) {\n              const networkError = new Error('网络连接失败，请稍后重试');\n              networkError.cause = error;\n              throw networkError;\n            }\n            await new Promise(resolve => setTimeout(resolve, 450));\n          }\n        }\n        let data;\n        try { data = await response.json(); } catch (_) { data = { error: '服务器返回异常' }; }\n        if (!response.ok) {\n          const error = new Error(data.error || '联机请求失败');\n          error.status = response.status;\n          error.data = data;\n          throw error;\n        }\n        return data;\n      }\n\n      function saveRoomSession() {\n        if (!state.room) return sessionStorage.removeItem('hangla-room');\n        sessionStorage.setItem('hangla-room', JSON.stringify({\n          code: state.room.code,\n          participantId: state.room.participantId,\n          nickname: state.room.nickname,\n          hostKey: state.room.hostKey || null\n        }));\n      }\n\n      function updateRoomAddress(code = null) {\n        const url = new URL(location.href);\n        if (code) url.searchParams.set('room', code);\n        else url.searchParams.delete('room');\n        history.replaceState(null, '', `${url.pathname}${url.search}${url.hash}`);\n      }\n\n      function updateRoomUi(payload = {}) {\n        if (!state.room) {\n          roomBar.hidden = true;\n          document.body.classList.remove('room-finalized');\n          document.querySelector('#roomBtn .button-label').textContent = '联机房间';\n          return;\n        }\n        if (typeof payload.version === 'number') state.room.version = payload.version;\n        if (typeof payload.finalized === 'boolean') state.room.finalized = payload.finalized;\n        if ('hostParticipantId' in payload) state.room.hostParticipantId = payload.hostParticipantId;\n        if (Array.isArray(payload.participants)) state.room.participants = payload.participants;\n        roomBar.hidden = false;\n        document.querySelector('#roomCode').textContent = state.room.code;\n        const people = state.room.participants || [];\n        document.querySelector('#roomPeople').textContent = people.length\n          ? `${people.length} 人在线 · ${people.map(person => person.name).join('、')}`\n          : '正在连接…';\n        const finalizeButton = document.querySelector('#finalizeBtn');\n        finalizeButton.hidden = !state.room.hostKey;\n        finalizeButton.textContent = state.room.finalized ? '解锁继续调整' : '锁定最终排名';\n        document.querySelector('#leaveRoomBtn').textContent = state.room.hostKey ? '交接 / 解散' : '退出房间';\n        document.body.classList.toggle('room-finalized', Boolean(state.room.finalized));\n        document.querySelector('#roomBtn .button-label').textContent = `房间 ${state.room.code}`;\n        document.querySelector('#addTierBtn').disabled = Boolean(state.room.finalized);\n        document.querySelector('#uploadBtn').disabled = Boolean(state.room.finalized);\n        document.querySelector('#bankUploadBtn').disabled = Boolean(state.room.finalized);\n        document.querySelector('#themeSelect').disabled = Boolean(state.room.finalized);\n        document.querySelector('#boardTitle').readOnly = Boolean(state.room.finalized);\n        maybeClaimRoomHost();\n      }\n\n      async function maybeClaimRoomHost() {\n        if (!state.room || state.room.hostKey || hostClaimInFlight) return;\n        if (state.room.hostParticipantId !== state.room.participantId) return;\n        const roomCode = state.room.code;\n        hostClaimInFlight = true;\n        try {\n          const data = await requestJson(`/api/rooms/${roomCode}/claim-host`, {\n            method: 'POST',\n            headers: { 'content-type': 'application/json' },\n            body: JSON.stringify({ participantId: state.room.participantId })\n          });\n          if (!state.room || state.room.code !== roomCode) return;\n          state.room.hostKey = data.hostKey;\n          saveRoomSession();\n          updateRoomUi(data);\n          say('你已成为新房主');\n        } catch (_) {\n          // 下一轮同步会再次尝试接管。\n        } finally {\n          hostClaimInFlight = false;\n        }\n      }\n\n      function scheduleRoomSync(delay = 80) {\n        if (!state.room || state.room.syncPaused || state.room.finalized || state.applyingRemote) return;\n        clearTimeout(roomSyncTimer);\n        roomSyncTimer = setTimeout(pushRoomState, delay);\n      }\n\n      async function pushRoomState() {\n        clearTimeout(roomSyncTimer);\n        if (!state.room || state.room.syncPaused || state.room.finalized || state.applyingRemote) return;\n        if (syncInFlight) {\n          syncQueued = true;\n          return;\n        }\n        syncInFlight = true;\n        try {\n          const data = await requestJson(`/api/rooms/${state.room.code}/sync`, {\n            method: 'PUT',\n            headers: { 'content-type': 'application/json' },\n            body: JSON.stringify({\n              participantId: state.room.participantId,\n              nickname: state.room.nickname,\n              baseVersion: state.room.version,\n              state: serializeBoard()\n            })\n          });\n          updateRoomUi(data);\n        } catch (error) {\n          if ([409, 423].includes(error.status) && error.data?.state) {\n            applyRemoteBoard(error.data.state);\n            updateRoomUi(error.data);\n            say(error.status === 423 ? '房主已锁定最终排名' : '已采用房间内较新的调整');\n          } else {\n            say('同步暂时中断，正在重试');\n            syncQueued = true;\n          }\n        } finally {\n          syncInFlight = false;\n          if (syncQueued) {\n            syncQueued = false;\n            scheduleRoomSync(220);\n          }\n        }\n      }\n\n      async function pollRoom() {\n        clearTimeout(roomPollTimer);\n        if (!state.room) return;\n        try {\n          const data = await requestJson(`/api/rooms/${state.room.code}?since=${state.room.version}`);\n          if (!syncInFlight && data.version > state.room.version && data.state) applyRemoteBoard(data.state);\n          updateRoomUi(data);\n        } catch (error) {\n          if (error.status === 404) leaveRoom(false, '房间已失效');\n        }\n        if (state.room) roomPollTimer = setTimeout(pollRoom, 100);\n      }\n\n      async function keepRoomPresence() {\n        clearTimeout(roomPresenceTimer);\n        if (!state.room) return;\n        try {\n          const data = await requestJson(`/api/rooms/${state.room.code}/presence`, {\n            method: 'POST',\n            headers: { 'content-type': 'application/json' },\n            body: JSON.stringify({ participantId: state.room.participantId, nickname: state.room.nickname })\n          });\n          updateRoomUi(data);\n        } catch (error) {\n          if (error.status === 404) leaveRoom(false, '房间已失效');\n        }\n        if (state.room) roomPresenceTimer = setTimeout(keepRoomPresence, 8000);\n      }\n\n      function beginRoom(data, nickname, hostKey = null, applyState = true) {\n        clearTimeout(roomPollTimer);\n        clearTimeout(roomPresenceTimer);\n        state.room = {\n          code: data.code,\n          participantId: data.participantId,\n          nickname,\n          hostKey,\n          hostParticipantId: data.hostParticipantId || (hostKey ? data.participantId : null),\n          version: data.version,\n          finalized: Boolean(data.finalized),\n          participants: data.participants || [],\n          syncPaused: false\n        };\n        updateRoomAddress(data.code);\n        if (applyState) applyRemoteBoard(data.state);\n        updateRoomUi(data);\n        saveRoomSession();\n        closeRoomModal();\n        roomPollTimer = setTimeout(pollRoom, 250);\n        roomPresenceTimer = setTimeout(keepRoomPresence, 6000);\n      }\n\n      function leaveRoom(confirmFirst = true, message = '已退出联机房间') {\n        if (confirmFirst && state.room?.hostKey) return openHostExitModal();\n        if (confirmFirst && !confirm('退出房间后会保留当前画面，但不再同步其他人的调整。确定退出吗？')) return;\n        clearTimeout(roomSyncTimer);\n        clearTimeout(roomPollTimer);\n        clearTimeout(roomPresenceTimer);\n        state.room = null;\n        updateRoomAddress();\n        syncInFlight = false;\n        syncQueued = false;\n        saveRoomSession();\n        updateRoomUi();\n        render();\n        say(message);\n      }\n\n      function openHostExitModal() {\n        if (!state.room?.hostKey) return;\n        const candidates = (state.room.participants || []).filter(person => person.id !== state.room.participantId);\n        const select = document.querySelector('#transferTargetSelect');\n        select.innerHTML = candidates.map(person => `<option value=\"${escapeHtml(person.id)}\">${escapeHtml(person.name)}</option>`).join('');\n        document.querySelector('#transferField').hidden = !candidates.length;\n        document.querySelector('#transferRoomBtn').hidden = !candidates.length;\n        document.querySelector('#hostExitNote').textContent = candidates.length\n          ? '转让后你会退出；解散后所有参与者都会离开，房间链接立即失效。'\n          : '当前没有其他参与者可以接任，房主只能解散房间。';\n        hostExitModal.classList.add('open');\n        hostExitModal.setAttribute('aria-hidden', 'false');\n      }\n\n      function closeHostExitModal() {\n        hostExitModal.classList.remove('open');\n        hostExitModal.setAttribute('aria-hidden', 'true');\n      }\n\n      async function transferRoomAndLeave() {\n        if (!state.room?.hostKey) return;\n        const button = document.querySelector('#transferRoomBtn');\n        const targetParticipantId = document.querySelector('#transferTargetSelect').value;\n        if (!targetParticipantId) return say('请选择接任房主');\n        button.disabled = true;\n        try {\n          await pushRoomState();\n          await requestJson(`/api/rooms/${state.room.code}/transfer`, {\n            method: 'POST',\n            headers: { 'content-type': 'application/json' },\n            body: JSON.stringify({ hostKey: state.room.hostKey, targetParticipantId })\n          });\n          closeHostExitModal();\n          leaveRoom(false, '房主已转让，你已退出房间');\n        } catch (error) {\n          say(error.message || '转让失败');\n        } finally {\n          button.disabled = false;\n        }\n      }\n\n      async function dissolveCurrentRoom() {\n        if (!state.room?.hostKey) return;\n        if (!confirm('确定解散房间吗？所有参与者都会离开，且无法恢复。')) return;\n        const button = document.querySelector('#dissolveRoomBtn');\n        button.disabled = true;\n        try {\n          await requestJson(`/api/rooms/${state.room.code}/dissolve`, {\n            method: 'POST',\n            headers: { 'content-type': 'application/json' },\n            body: JSON.stringify({ hostKey: state.room.hostKey })\n          });\n          closeHostExitModal();\n          leaveRoom(false, '房间已解散');\n        } catch (error) {\n          say(error.message || '解散失败');\n        } finally {\n          button.disabled = false;\n        }\n      }\n\n      function openRoomModal() {\n        roomModal.classList.add('open');\n        roomModal.setAttribute('aria-hidden', 'false');\n        let savedName = state.room?.nickname || '';\n        try { savedName ||= JSON.parse(sessionStorage.getItem('hangla-room') || 'null')?.nickname || ''; } catch (_) {}\n        document.querySelector('#nicknameInput').value = savedName;\n        setTimeout(() => document.querySelector(savedName ? '#joinCodeInput' : '#nicknameInput').focus(), 0);\n      }\n\n      function closeRoomModal() {\n        roomModal.classList.remove('open');\n        roomModal.setAttribute('aria-hidden', 'true');\n      }\n\n      async function mapWithConcurrency(entries, limit, worker) {\n        const results = new Array(entries.length);\n        let nextIndex = 0;\n        async function run() {\n          while (nextIndex < entries.length) {\n            const index = nextIndex++;\n            results[index] = await worker(entries[index], index);\n          }\n        }\n        await Promise.all(Array.from({ length: Math.min(limit, entries.length) }, run));\n        return results;\n      }\n\n      async function optimizeImageForUpload(blob) {\n        if (!['image/jpeg', 'image/png', 'image/webp'].includes(blob.type) || blob.size < 900000) return blob;\n        try {\n          const bitmap = await createImageBitmap(blob);\n          const scale = Math.min(1, 1600 / Math.max(bitmap.width, bitmap.height));\n          const canvas = document.createElement('canvas');\n          canvas.width = Math.max(1, Math.round(bitmap.width * scale));\n          canvas.height = Math.max(1, Math.round(bitmap.height * scale));\n          canvas.getContext('2d').drawImage(bitmap, 0, 0, canvas.width, canvas.height);\n          bitmap.close();\n          const optimized = await new Promise(resolve => canvas.toBlob(resolve, 'image/webp', .86));\n          return optimized && optimized.size < blob.size ? optimized : blob;\n        } catch (_) {\n          return blob;\n        }\n      }\n\n      async function uploadBlobToRoom(blob, name) {\n        const uploadBlob = await optimizeImageForUpload(blob);\n        const response = await requestJson(`/api/rooms/${state.room.code}/images`, {\n          method: 'POST',\n          headers: { 'content-type': uploadBlob.type, 'x-file-name': encodeURIComponent(name) },\n          body: uploadBlob\n        });\n        return response;\n      }\n\n      async function createRoom() {\n        const button = document.querySelector('#createRoomBtn');\n        const nickname = document.querySelector('#nicknameInput').value.trim();\n        if (!nickname) return say('请先填写昵称');\n        button.disabled = true;\n        button.textContent = '创建中…';\n        try {\n          const participantId = crypto.randomUUID();\n          const data = await requestJson('/api/rooms', {\n            method: 'POST',\n            headers: { 'content-type': 'application/json' },\n            body: JSON.stringify({ participantId, nickname, state: serializeBoard(true) })\n          });\n          beginRoom(data, nickname, data.hostKey, false);\n          state.room.syncPaused = true;\n          const failed = [];\n          await mapWithConcurrency([...state.items.values()], 4, async item => {\n            try {\n              const blob = await fetch(item.url).then(response => response.blob());\n              const uploaded = await uploadBlobToRoom(blob, item.name);\n              if (item.url.startsWith('blob:')) URL.revokeObjectURL(item.url);\n              item.url = uploaded.url;\n              item.remoteId = uploaded.id;\n            } catch (_) {\n              failed.push(item.id);\n            }\n          });\n          failed.forEach(id => {\n            const location = locateItem(id);\n            if (location) location.list.splice(location.list.indexOf(id), 1);\n            state.items.delete(id);\n          });\n          state.room.syncPaused = false;\n          render();\n          await pushRoomState();\n          say(failed.length ? `房间已创建，${failed.length} 张图片上传失败` : `房间 ${data.code} 已创建`);\n        } catch (error) {\n          say(error.message || '创建房间失败');\n        } finally {\n          button.disabled = false;\n          button.textContent = '创建新房间';\n        }\n      }\n\n      async function joinRoom() {\n        const button = document.querySelector('#joinRoomBtn');\n        const nickname = document.querySelector('#nicknameInput').value.trim();\n        const code = document.querySelector('#joinCodeInput').value.toUpperCase().replace(/[^A-Z0-9]/g, '');\n        if (!nickname) return say('请先填写昵称');\n        if (code.length !== 8) return say('请输入 8 位字母或数字房间号');\n        if (allItemIds().length && !confirm('加入房间会用房间里的共同排名替换当前画面，确定加入吗？')) return;\n        button.disabled = true;\n        button.textContent = '加入中…';\n        try {\n          const participantId = crypto.randomUUID();\n          const data = await requestJson(`/api/rooms/${code}/join`, {\n            method: 'POST',\n            headers: { 'content-type': 'application/json' },\n            body: JSON.stringify({ participantId, nickname })\n          });\n          beginRoom(data, nickname, null, true);\n          say(`已加入房间 ${code}`);\n        } catch (error) {\n          say(error.message || '加入房间失败');\n        } finally {\n          button.disabled = false;\n          button.textContent = '加入房间';\n        }\n      }\n\n      async function resumeRoom() {\n        let saved;\n        try { saved = JSON.parse(sessionStorage.getItem('hangla-room') || 'null'); } catch (_) {}\n        if (!saved?.code || !saved?.nickname || !saved?.participantId) return false;\n        try {\n          const data = await requestJson(`/api/rooms/${saved.code}/join`, {\n            method: 'POST',\n            headers: { 'content-type': 'application/json' },\n            body: JSON.stringify({ participantId: saved.participantId, nickname: saved.nickname })\n          });\n          beginRoom(data, saved.nickname, saved.hostKey || null, true);\n          say(`已恢复房间 ${saved.code}`);\n          return true;\n        } catch (_) {\n          sessionStorage.removeItem('hangla-room');\n          return false;\n        }\n      }\n\n      async function copyRoomInvite() {\n        if (!state.room) return;\n        const inviteUrl = `${location.origin}${location.pathname}?room=${state.room.code}`;\n        try {\n          await navigator.clipboard.writeText(`加入我的夯拉板房间 ${state.room.code}：${inviteUrl}`);\n          say('邀请链接和房间号已复制');\n        } catch (_) {\n          window.prompt('复制这段邀请信息', `房间 ${state.room.code}：${inviteUrl}`);\n        }\n      }\n\n      async function toggleFinalized() {\n        if (!state.room?.hostKey) return;\n        await pushRoomState();\n        try {\n          const data = await requestJson(`/api/rooms/${state.room.code}/finalize`, {\n            method: 'POST',\n            headers: { 'content-type': 'application/json' },\n            body: JSON.stringify({ hostKey: state.room.hostKey, finalized: !state.room.finalized })\n          });\n          if (data.state) applyRemoteBoard(data.state);\n          updateRoomUi(data);\n          say(data.finalized ? '最终排名已锁定，所有人暂停编辑' : '排名已解锁，可以继续调整');\n        } catch (error) {\n          say(error.message || '操作失败');\n        }\n      }\n\n      function allItemIds() {\n        return [...state.bank, ...state.tiers.flatMap(tier => tier.items)];\n      }\n\n      function themeColorAt(index) {\n        const palette = THEMES[state.theme];\n        return state.theme === 'rainbow' ? palette[index % palette.length] : palette[Math.min(index, palette.length - 1)];\n      }\n\n      function applyTheme(themeName) {\n        if (!THEMES[themeName] || !canEdit()) return;\n        state.theme = themeName;\n        render();\n        say(themeName === 'rainbow' ? '已切换为彩虹色' : '已切换为红橙黄白');\n      }\n\n      function locateItem(id) {\n        if (state.bank.includes(id)) return { type: 'bank', list: state.bank };\n        const tier = state.tiers.find(entry => entry.items.includes(id));\n        return tier ? { type: 'tier', list: tier.items, tier } : null;\n      }\n\n      function moveItem(id, targetType, targetId, beforeId = null) {\n        if (!canEdit()) return;\n        const source = locateItem(id);\n        if (!source) return;\n        source.list.splice(source.list.indexOf(id), 1);\n        const target = targetType === 'bank' ? state.bank : state.tiers.find(t => t.id === targetId)?.items;\n        if (!target) return;\n        const targetIndex = beforeId ? target.indexOf(beforeId) : -1;\n        target.splice(targetIndex >= 0 ? targetIndex : target.length, 0, id);\n        render();\n      }\n\n      function tileElement(id) {\n        const item = state.items.get(id);\n        const tile = document.createElement('article');\n        tile.className = 'tile';\n        tile.draggable = !state.room?.finalized;\n        tile.dataset.itemId = id;\n        tile.title = item.name;\n        tile.innerHTML = `<img alt=\"${escapeHtml(item.name)}\"><button type=\"button\" aria-label=\"删除 ${escapeHtml(item.name)}\">×</button>`;\n        tile.querySelector('img').src = item.url;\n\n        tile.addEventListener('dragstart', event => {\n          if (!canEdit()) return event.preventDefault();\n          state.draggingId = id;\n          event.dataTransfer.effectAllowed = 'move';\n          event.dataTransfer.setData('text/plain', id);\n          requestAnimationFrame(() => tile.classList.add('dragging'));\n        });\n        tile.addEventListener('dragend', () => {\n          state.draggingId = null;\n          tile.classList.remove('dragging');\n          document.querySelectorAll('.drag-over').forEach(el => el.classList.remove('drag-over'));\n        });\n        tile.addEventListener('dragover', event => {\n          if (!state.draggingId || state.draggingId === id) return;\n          event.preventDefault();\n        });\n        tile.addEventListener('drop', event => {\n          if (!state.draggingId || state.draggingId === id) return;\n          event.preventDefault();\n          event.stopPropagation();\n          const parent = tile.parentElement;\n          moveItem(state.draggingId, parent.dataset.zone, parent.dataset.tierId, id);\n        });\n        tile.querySelector('button').addEventListener('click', () => removeItem(id));\n        return tile;\n      }\n\n      function escapeHtml(value) {\n        return value.replace(/[&<>'\"]/g, char => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', \"'\":'&#39;', '\"':'&quot;' })[char]);\n      }\n\n      function attachZoneEvents(zone, type, id = '') {\n        zone.addEventListener('dragover', event => {\n          if (!state.draggingId) return;\n          event.preventDefault();\n          event.dataTransfer.dropEffect = 'move';\n          zone.classList.add('drag-over');\n        });\n        zone.addEventListener('dragleave', event => {\n          if (!zone.contains(event.relatedTarget)) zone.classList.remove('drag-over');\n        });\n        zone.addEventListener('drop', event => {\n          if (!state.draggingId) return;\n          event.preventDefault();\n          zone.classList.remove('drag-over');\n          moveItem(state.draggingId, type, id);\n        });\n      }\n\n      function render() {\n        board.innerHTML = '';\n        document.body.style.setProperty('--tier-count', Math.max(state.tiers.length, 1));\n        state.tiers.forEach((tier, index) => {\n          const row = document.createElement('div');\n          row.className = 'tier';\n          row.dataset.tierId = tier.id;\n          row.style.setProperty('--tier-color', themeColorAt(index));\n          row.innerHTML = `\n            <div class=\"tier-name\"><input value=\"${escapeHtml(tier.name)}\" aria-label=\"档位名称\"></div>\n            <div class=\"tier-drop\" data-zone=\"tier\" data-tier-id=\"${tier.id}\"></div>\n            <div class=\"tier-tools\">\n              <button class=\"drag-tier\" type=\"button\" draggable=\"true\" aria-label=\"拖动 ${escapeHtml(tier.name)} 档调整顺序\" title=\"拖动调整档位顺序\">⠿</button>\n              <button class=\"delete-tier\" type=\"button\" aria-label=\"删除 ${escapeHtml(tier.name)} 档\">×</button>\n            </div>`;\n          const input = row.querySelector('input');\n          input.readOnly = Boolean(state.room?.finalized);\n          input.addEventListener('input', () => {\n            if (!canEdit()) return;\n            tier.name = input.value;\n            scheduleRoomSync(100);\n          });\n          row.querySelector('.delete-tier').addEventListener('click', () => deleteTier(tier.id));\n          const dragHandle = row.querySelector('.drag-tier');\n          dragHandle.draggable = !state.room?.finalized;\n          dragHandle.addEventListener('dragstart', event => {\n            if (!canEdit()) return event.preventDefault();\n            state.draggingTierId = tier.id;\n            event.dataTransfer.effectAllowed = 'move';\n            event.dataTransfer.setData('text/plain', `tier:${tier.id}`);\n          });\n          dragHandle.addEventListener('dragend', () => {\n            state.draggingTierId = null;\n            document.querySelectorAll('.tier-drag-before, .tier-drag-after').forEach(el => el.classList.remove('tier-drag-before', 'tier-drag-after'));\n          });\n          row.addEventListener('dragover', event => {\n            if (!state.draggingTierId || state.draggingTierId === tier.id) return;\n            event.preventDefault();\n            const isAfter = event.clientY > row.getBoundingClientRect().top + row.getBoundingClientRect().height / 2;\n            row.classList.toggle('tier-drag-before', !isAfter);\n            row.classList.toggle('tier-drag-after', isAfter);\n          });\n          row.addEventListener('dragleave', event => {\n            if (!row.contains(event.relatedTarget)) row.classList.remove('tier-drag-before', 'tier-drag-after');\n          });\n          row.addEventListener('drop', event => {\n            if (!state.draggingTierId || state.draggingTierId === tier.id) return;\n            event.preventDefault();\n            event.stopPropagation();\n            const isAfter = event.clientY > row.getBoundingClientRect().top + row.getBoundingClientRect().height / 2;\n            const movingIndex = state.tiers.findIndex(entry => entry.id === state.draggingTierId);\n            const [movingTier] = state.tiers.splice(movingIndex, 1);\n            let targetIndex = state.tiers.findIndex(entry => entry.id === tier.id);\n            if (isAfter) targetIndex += 1;\n            state.tiers.splice(targetIndex, 0, movingTier);\n            state.draggingTierId = null;\n            render();\n            say('档位顺序已调整');\n          });\n          const zone = row.querySelector('.tier-drop');\n          attachZoneEvents(zone, 'tier', tier.id);\n          tier.items.forEach(itemId => zone.appendChild(tileElement(itemId)));\n          board.appendChild(row);\n        });\n\n        bank.innerHTML = '';\n        attachZoneEvents(bank, 'bank');\n        state.bank.forEach(id => bank.appendChild(tileElement(id)));\n        if (!state.bank.length) {\n          const empty = document.createElement('div');\n          empty.className = 'empty';\n          empty.innerHTML = allItemIds().length ? '所有图片都已经完成分档。<br>也可以把图片拖回这里。' : '把图片拖到这里，或点击“上传图片”开始。<br>支持一次选择多张。';\n          bank.appendChild(empty);\n        }\n        itemCount.textContent = `${state.bank.length} 张`;\n        if (state.room && !state.applyingRemote) scheduleRoomSync();\n      }\n\n      function addTier(name = '新档位') {\n        if (!canEdit()) return;\n        state.tiers.push({ id: crypto.randomUUID(), name, items: [] });\n        render();\n        say('已增加一个档位');\n      }\n\n      function deleteTier(id) {\n        if (!canEdit()) return;\n        if (state.tiers.length <= 1) return say('至少保留一个档位');\n        const tier = state.tiers.find(entry => entry.id === id);\n        if (!tier || !confirm(`删除“${tier.name || '未命名'}”档？其中图片会回到待分档区。`)) return;\n        state.bank.push(...tier.items);\n        state.tiers = state.tiers.filter(entry => entry.id !== id);\n        render();\n        say('档位已删除');\n      }\n\n      function removeItem(id) {\n        if (!canEdit()) return;\n        const item = state.items.get(id);\n        if (!item) return;\n        const location = locateItem(id);\n        if (location) location.list.splice(location.list.indexOf(id), 1);\n        URL.revokeObjectURL(item.url);\n        state.items.delete(id);\n        render();\n      }\n\n      async function addFiles(fileList) {\n        if (!canEdit()) return;\n        const files = [...fileList].filter(file => file.type.startsWith('image/'));\n        if (!files.length) return say('请选择图片文件');\n        if (state.room) say(`正在上传 ${files.length} 张图片…`);\n        const results = await mapWithConcurrency(files, state.room ? 4 : 12, async file => {\n          const id = crypto.randomUUID();\n          const name = file.name.replace(/\\.[^.]+$/, '');\n          try {\n            if (state.room) {\n              const uploaded = await uploadBlobToRoom(file, name);\n              state.items.set(id, { id, name, url: uploaded.url, remoteId: uploaded.id });\n            } else {\n              state.items.set(id, { id, name, url: URL.createObjectURL(file), remoteId: null });\n            }\n            return id;\n          } catch (error) {\n            console.error(error);\n            return null;\n          }\n        });\n        const successfulIds = results.filter(Boolean);\n        state.bank.push(...successfulIds);\n        const added = successfulIds.length;\n        render();\n        say(added === files.length ? `已添加 ${added} 张图片` : `已添加 ${added} 张，${files.length - added} 张失败`);\n      }\n\n      function roundedRect(ctx, x, y, width, height, radius) {\n        const r = Math.min(radius, width / 2, height / 2);\n        ctx.beginPath();\n        ctx.moveTo(x + r, y);\n        ctx.arcTo(x + width, y, x + width, y + height, r);\n        ctx.arcTo(x + width, y + height, x, y + height, r);\n        ctx.arcTo(x, y + height, x, y, r);\n        ctx.arcTo(x, y, x + width, y, r);\n        ctx.closePath();\n      }\n\n      function drawFittedText(ctx, text, x, y, maxWidth, maxSize = 34, minSize = 20) {\n        let size = maxSize;\n        do {\n          ctx.font = `900 ${size}px Inter, \"PingFang SC\", \"Microsoft YaHei\", sans-serif`;\n          if (ctx.measureText(text).width <= maxWidth) break;\n          size -= 1;\n        } while (size > minSize);\n        ctx.fillText(text, x, y, maxWidth);\n      }\n\n      function drawCoverImage(ctx, image, x, y, size) {\n        const sourceRatio = image.naturalWidth / image.naturalHeight;\n        let sourceWidth = image.naturalWidth;\n        let sourceHeight = image.naturalHeight;\n        let sourceX = 0;\n        let sourceY = 0;\n        if (sourceRatio > 1) {\n          sourceWidth = image.naturalHeight;\n          sourceX = (image.naturalWidth - sourceWidth) / 2;\n        } else {\n          sourceHeight = image.naturalWidth;\n          sourceY = (image.naturalHeight - sourceHeight) / 2;\n        }\n        ctx.save();\n        roundedRect(ctx, x, y, size, size, 10);\n        ctx.clip();\n        ctx.drawImage(image, sourceX, sourceY, sourceWidth, sourceHeight, x, y, size, size);\n        ctx.restore();\n        ctx.strokeStyle = 'rgba(255,255,255,.18)';\n        ctx.lineWidth = 2;\n        roundedRect(ctx, x, y, size, size, 10);\n        ctx.stroke();\n      }\n\n      function loadExportImage(url) {\n        return new Promise(resolve => {\n          const image = new Image();\n          image.onload = () => resolve(image);\n          image.onerror = () => resolve(null);\n          image.src = url;\n        });\n      }\n\n      function drawTierLabel(ctx, name, x, y, width, height) {\n        const value = (name || '未命名').trim() || '未命名';\n        const maxChars = 7;\n        const lines = [];\n        for (let index = 0; index < value.length; index += maxChars) lines.push(value.slice(index, index + maxChars));\n        const visibleLines = lines.slice(0, 3);\n        if (lines.length > 3) visibleLines[2] = `${visibleLines[2].slice(0, Math.max(1, maxChars - 1))}…`;\n        const fontSize = visibleLines.length > 2 ? 23 : 27;\n        const lineHeight = fontSize * 1.24;\n        const startY = y + height / 2 - ((visibleLines.length - 1) * lineHeight) / 2;\n        ctx.fillStyle = '#151515';\n        ctx.font = `900 ${fontSize}px Inter, \"PingFang SC\", \"Microsoft YaHei\", sans-serif`;\n        ctx.textAlign = 'center';\n        ctx.textBaseline = 'middle';\n        visibleLines.forEach((line, index) => ctx.fillText(line, x + width / 2, startY + index * lineHeight, width - 24));\n      }\n\n      async function exportBoard() {\n        const exportButton = document.querySelector('#exportBtn');\n        const rankedIds = state.tiers.flatMap(tier => tier.items);\n        if (!rankedIds.length) return say('请先将至少一张图片放入档位');\n        const exportTitle = state.title.trim() || '未命名排序';\n\n        exportButton.disabled = true;\n        exportButton.setAttribute('aria-busy', 'true');\n        const originalLabel = exportButton.querySelector('.button-label').textContent;\n        exportButton.querySelector('.button-label').textContent = '生成中';\n\n        try {\n          await document.fonts?.ready;\n          const loadedEntries = await Promise.all(rankedIds.map(async id => {\n            const item = state.items.get(id);\n            return [id, item ? await loadExportImage(item.url) : null];\n          }));\n          const loadedImages = new Map(loadedEntries);\n\n          const canvasWidth = 1600;\n          const outerPadding = 44;\n          const headerHeight = 146;\n          const footerHeight = 74;\n          const labelWidth = 190;\n          const tileSize = 116;\n          const gap = 12;\n          const rowPadding = 18;\n          const boardWidth = canvasWidth - outerPadding * 2;\n          const contentWidth = boardWidth - labelWidth;\n          const perRow = Math.max(1, Math.floor((contentWidth - rowPadding * 2 + gap) / (tileSize + gap)));\n          const rowHeights = state.tiers.map(tier => {\n            const imageRows = Math.max(1, Math.ceil(tier.items.length / perRow));\n            return Math.max(154, rowPadding * 2 + imageRows * tileSize + (imageRows - 1) * gap);\n          });\n          const canvasHeight = headerHeight + rowHeights.reduce((sum, height) => sum + height, 0) + footerHeight;\n          const targetPixels = 26000000;\n          const scale = Math.min(2, Math.max(.65, Math.sqrt(targetPixels / (canvasWidth * canvasHeight))));\n          const canvas = document.createElement('canvas');\n          canvas.width = Math.round(canvasWidth * scale);\n          canvas.height = Math.round(canvasHeight * scale);\n          const ctx = canvas.getContext('2d');\n          ctx.scale(scale, scale);\n\n          ctx.fillStyle = '#0b0d10';\n          ctx.fillRect(0, 0, canvasWidth, canvasHeight);\n\n          ctx.fillStyle = '#eaff5b';\n          roundedRect(ctx, outerPadding, 42, 58, 58, 14);\n          ctx.fill();\n          ctx.fillStyle = '#151800';\n          ctx.font = '1000 31px Inter, \"PingFang SC\", sans-serif';\n          ctx.textAlign = 'center';\n          ctx.textBaseline = 'middle';\n          ctx.fillText('夯', outerPadding + 29, 72);\n\n          ctx.fillStyle = '#f5f6f7';\n          ctx.textAlign = 'left';\n          drawFittedText(ctx, exportTitle, outerPadding + 78, 61, canvasWidth - outerPadding * 2 - 350);\n          ctx.fillStyle = '#9aa3ae';\n          ctx.font = '500 20px Inter, \"PingFang SC\", sans-serif';\n          ctx.fillText('夯拉板 · 分档结果', outerPadding + 78, 91);\n          ctx.textAlign = 'right';\n          ctx.fillText(state.theme === 'rainbow' ? '彩虹色主题' : '红橙黄白主题', canvasWidth - outerPadding, 74);\n\n          let rowY = headerHeight;\n          state.tiers.forEach((tier, tierIndex) => {\n            const rowHeight = rowHeights[tierIndex];\n            ctx.fillStyle = themeColorAt(tierIndex);\n            ctx.fillRect(outerPadding, rowY, labelWidth, rowHeight);\n            ctx.fillStyle = '#15191f';\n            ctx.fillRect(outerPadding + labelWidth, rowY, contentWidth, rowHeight);\n            drawTierLabel(ctx, tier.name, outerPadding, rowY, labelWidth, rowHeight);\n\n            tier.items.forEach((id, itemIndex) => {\n              const column = itemIndex % perRow;\n              const imageRow = Math.floor(itemIndex / perRow);\n              const x = outerPadding + labelWidth + rowPadding + column * (tileSize + gap);\n              const y = rowY + rowPadding + imageRow * (tileSize + gap);\n              const image = loadedImages.get(id);\n              if (image) {\n                drawCoverImage(ctx, image, x, y, tileSize);\n              } else {\n                ctx.fillStyle = '#2a3039';\n                roundedRect(ctx, x, y, tileSize, tileSize, 10);\n                ctx.fill();\n              }\n            });\n\n            ctx.strokeStyle = '#2a3039';\n            ctx.lineWidth = 2;\n            ctx.beginPath();\n            ctx.moveTo(outerPadding, rowY + rowHeight);\n            ctx.lineTo(canvasWidth - outerPadding, rowY + rowHeight);\n            ctx.stroke();\n            rowY += rowHeight;\n          });\n\n          ctx.strokeStyle = '#343b45';\n          ctx.lineWidth = 2;\n          ctx.strokeRect(outerPadding, headerHeight, boardWidth, rowY - headerHeight);\n\n          ctx.fillStyle = '#9aa3ae';\n          ctx.font = '500 18px Inter, \"PingFang SC\", sans-serif';\n          ctx.textBaseline = 'middle';\n          ctx.textAlign = 'left';\n          ctx.fillText(`共 ${rankedIds.length} 张 · ${state.tiers.length} 个档位`, outerPadding, rowY + footerHeight / 2);\n          ctx.textAlign = 'right';\n          ctx.fillText('由夯拉板生成', canvasWidth - outerPadding, rowY + footerHeight / 2);\n\n          const blob = await new Promise(resolve => canvas.toBlob(resolve, 'image/png'));\n          if (!blob) throw new Error('无法生成图片');\n          const downloadUrl = URL.createObjectURL(blob);\n          const link = document.createElement('a');\n          link.href = downloadUrl;\n          const safeTitle = exportTitle.replace(/[\\\\/:*?\"<>|]/g, '').replace(/\\s+/g, ' ').trim().slice(0, 80) || '未命名排序';\n          link.download = `${safeTitle}.png`;\n          document.body.appendChild(link);\n          link.click();\n          link.remove();\n          setTimeout(() => URL.revokeObjectURL(downloadUrl), 1000);\n          say(state.bank.length ? `已导出，待分档的 ${state.bank.length} 张未包含` : '分档结果已导出为 PNG');\n        } catch (error) {\n          console.error(error);\n          say('导出失败，请稍后重试');\n        } finally {\n          exportButton.disabled = false;\n          exportButton.removeAttribute('aria-busy');\n          exportButton.querySelector('.button-label').textContent = originalLabel;\n        }\n      }\n\n      async function toggleRecording(force) {\n        const entering = typeof force === 'boolean' ? force : !document.body.classList.contains('recording');\n        document.body.classList.toggle('recording', entering);\n        if (entering) {\n          try { await document.documentElement.requestFullscreen?.(); } catch (_) {}\n        } else if (document.fullscreenElement) {\n          try { await document.exitFullscreen(); } catch (_) {}\n        }\n      }\n\n      document.querySelector('#addTierBtn').addEventListener('click', () => addTier());\n      document.querySelector('#boardTitle').addEventListener('input', event => {\n        if (!canEdit()) return;\n        state.title = event.target.value;\n        scheduleRoomSync(100);\n      });\n      document.querySelector('#themeSelect').addEventListener('change', event => applyTheme(event.target.value));\n      document.querySelector('#uploadBtn').addEventListener('click', () => fileInput.click());\n      document.querySelector('#bankUploadBtn').addEventListener('click', () => fileInput.click());\n      document.querySelector('#roomBtn').addEventListener('click', () => state.room ? copyRoomInvite() : openRoomModal());\n      document.querySelector('#roomCloseBtn').addEventListener('click', closeRoomModal);\n      document.querySelector('#createRoomBtn').addEventListener('click', createRoom);\n      document.querySelector('#joinRoomBtn').addEventListener('click', joinRoom);\n      document.querySelector('#copyRoomBtn').addEventListener('click', copyRoomInvite);\n      document.querySelector('#finalizeBtn').addEventListener('click', toggleFinalized);\n      document.querySelector('#leaveRoomBtn').addEventListener('click', () => leaveRoom(true));\n      document.querySelector('#hostExitCloseBtn').addEventListener('click', closeHostExitModal);\n      document.querySelector('#transferRoomBtn').addEventListener('click', transferRoomAndLeave);\n      document.querySelector('#dissolveRoomBtn').addEventListener('click', dissolveCurrentRoom);\n      document.querySelector('#joinCodeInput').addEventListener('input', event => {\n        event.target.value = event.target.value.toUpperCase().replace(/[^A-Z0-9]/g, '').slice(0, 8);\n      });\n      roomModal.addEventListener('click', event => { if (event.target === roomModal) closeRoomModal(); });\n      hostExitModal.addEventListener('click', event => { if (event.target === hostExitModal) closeHostExitModal(); });\n      document.querySelector('#exportBtn').addEventListener('click', exportBoard);\n      document.querySelector('#recordBtn').addEventListener('click', () => toggleRecording(true));\n      fileInput.addEventListener('change', async () => { await addFiles(fileInput.files); fileInput.value = ''; });\n\n      window.addEventListener('keydown', event => {\n        if (event.key === 'Escape' && roomModal.classList.contains('open')) closeRoomModal();\n        if (event.key === 'Escape' && hostExitModal.classList.contains('open')) closeHostExitModal();\n        if (event.key === 'Escape' && document.body.classList.contains('recording')) toggleRecording(false);\n        if (event.key.toLowerCase() === 'r' && !['INPUT', 'TEXTAREA'].includes(document.activeElement.tagName)) toggleRecording();\n      });\n      document.addEventListener('fullscreenchange', () => {\n        if (!document.fullscreenElement) document.body.classList.remove('recording');\n      });\n\n      window.addEventListener('dragenter', event => {\n        if (!event.dataTransfer?.types.includes('Files')) return;\n        externalDragDepth++;\n        dropMask.classList.add('visible');\n      });\n      window.addEventListener('dragleave', event => {\n        if (!event.dataTransfer?.types.includes('Files')) return;\n        externalDragDepth--;\n        if (externalDragDepth <= 0) { externalDragDepth = 0; dropMask.classList.remove('visible'); }\n      });\n      window.addEventListener('dragover', event => {\n        if (event.dataTransfer?.types.includes('Files')) event.preventDefault();\n      });\n      window.addEventListener('drop', event => {\n        if (!event.dataTransfer?.files?.length) return;\n        event.preventDefault();\n        externalDragDepth = 0;\n        dropMask.classList.remove('visible');\n        addFiles(event.dataTransfer.files);\n      });\n\n      function registerWebMcpTools() {\n        const context = document.modelContext;\n        if (!context?.registerTool) return;\n        const lifecycle = new AbortController();\n        const options = { signal: lifecycle.signal };\n        const onError = error => console.warn('WebMCP tool registration failed', error);\n        const register = tool => {\n          try { Promise.resolve(context.registerTool(tool, options)).catch(onError); } catch (error) { onError(error); }\n        };\n\n        register({\n          name: 'set_tier_theme',\n          title: '设置档位主题',\n          description: '将所有现有档位切换为彩虹色或红橙黄白配色。',\n          inputSchema: { type: 'object', properties: { theme: { type: 'string', enum: ['rainbow', 'ember'] } }, required: ['theme'], additionalProperties: false },\n          annotations: { readOnlyHint: false, untrustedContentHint: false },\n          execute(input) {\n            if (!input || !THEMES[input.theme]) throw new Error('主题必须是 rainbow 或 ember');\n            applyTheme(input.theme);\n            return { applied: true, theme: state.theme, colors: state.tiers.map((_, index) => themeColorAt(index)) };\n          }\n        });\n\n        register({\n          name: 'add_tier',\n          title: '增加档位',\n          description: '在夯拉板底部增加一个新的空档位。',\n          inputSchema: { type: 'object', properties: { name: { type: 'string', minLength: 1, maxLength: 30 } }, required: ['name'], additionalProperties: false },\n          annotations: { readOnlyHint: false, untrustedContentHint: false },\n          execute(input) {\n            if (!input || typeof input.name !== 'string' || !input.name.trim() || input.name.length > 30) throw new Error('档位名称必须是 1–30 个字符');\n            addTier(input.name.trim());\n            return { added: true, tierName: input.name.trim(), tierCount: state.tiers.length };\n          }\n        });\n\n        register({\n          name: 'read_board',\n          title: '读取看板',\n          description: '读取当前档位名称以及每档图片数量，不修改看板。',\n          inputSchema: { type: 'object', properties: {}, additionalProperties: false },\n          annotations: { readOnlyHint: true, untrustedContentHint: true },\n          execute() {\n            return { tiers: state.tiers.map(tier => ({ name: tier.name, itemCount: tier.items.length })), unrankedCount: state.bank.length };\n          }\n        });\n      }\n\n      render();\n      registerWebMcpTools();\n      (async () => {\n        const resumed = await resumeRoom();\n        if (resumed) return;\n        const invitedCode = new URLSearchParams(location.search).get('room')?.toUpperCase().replace(/[^A-Z0-9]/g, '').slice(0, 8);\n        if (invitedCode?.length === 8) {\n          document.querySelector('#joinCodeInput').value = invitedCode;\n          openRoomModal();\n        }\n      })();\n    })();\n  </script>\n</body>\n</html>\n";

const JSON_HEADERS = {
  'content-type': 'application/json; charset=utf-8',
  'cache-control': 'no-store',
};
const ROOM_CODE_PATTERN = /^[A-Z0-9]{8}$/;
const ROOM_CODE_ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
const IMAGE_TYPES = new Set(['image/png', 'image/jpeg', 'image/webp', 'image/gif']);
const MAX_IMAGE_BYTES = 8 * 1024 * 1024;

function json(data, status = 200) {
  return new Response(JSON.stringify(data), { status, headers: JSON_HEADERS });
}

function randomRoomCode() {
  const bytes = new Uint8Array(8);
  crypto.getRandomValues(bytes);
  return [...bytes].map(value => ROOM_CODE_ALPHABET[value % ROOM_CODE_ALPHABET.length]).join('');
}

function cleanName(value, fallback = '参与者') {
  const name = String(value || '').trim().slice(0, 24);
  return name || fallback;
}

function cleanRoomCode(value) {
  const code = String(value || '').toUpperCase().replace(/[^A-Z0-9]/g, '').slice(0, 8);
  return ROOM_CODE_PATTERN.test(code) ? code : null;
}

function cleanBoardState(value) {
  if (!value || typeof value !== 'object') throw new Error('看板数据无效');
  const tiers = Array.isArray(value.tiers) ? value.tiers.slice(0, 20) : [];
  const items = Array.isArray(value.items) ? value.items.slice(0, 200) : [];
  const knownItemIds = new Set(items.map(item => String(item?.id || '')).filter(Boolean));
  return {
    title: String(value.title || '这期怎么排？').slice(0, 80),
    theme: value.theme === 'ember' ? 'ember' : 'rainbow',
    tiers: tiers.map((tier, index) => ({
      id: String(tier?.id || crypto.randomUUID()).slice(0, 80),
      name: String(tier?.name || `档位 ${index + 1}`).slice(0, 30),
      items: Array.isArray(tier?.items)
        ? tier.items.map(String).filter(id => knownItemIds.has(id)).slice(0, 200)
        : [],
    })),
    bank: Array.isArray(value.bank)
      ? value.bank.map(String).filter(id => knownItemIds.has(id)).slice(0, 200)
      : [],
    items: items.map(item => ({
      id: String(item?.id || crypto.randomUUID()).slice(0, 80),
      name: String(item?.name || '图片').slice(0, 120),
      url: String(item?.url || '').slice(0, 300),
      remoteId: item?.remoteId ? String(item.remoteId).slice(0, 80) : null,
    })),
  };
}

async function readBody(request) {
  const length = Number(request.headers.get('content-length') || 0);
  if (length > 400000) throw new Error('请求内容过大');
  return request.json();
}

async function getRoom(env, code) {
  return env.DB.prepare(
    'SELECT code, host_participant_id, state_json, version, finalized, updated_at FROM rooms WHERE code = ?',
  ).bind(code).first();
}

async function activeParticipants(env, code) {
  const cutoff = Date.now() - 30000;
  const result = await env.DB.prepare(
    'SELECT id, name, last_seen FROM participants WHERE room_code = ? AND last_seen >= ? ORDER BY last_seen DESC',
  ).bind(code, cutoff).all();
  return (result.results || []).map(entry => ({
    id: entry.id,
    name: entry.name,
    lastSeen: entry.last_seen,
  }));
}

async function touchParticipant(env, code, participantId, nickname) {
  const id = String(participantId || '').slice(0, 80) || crypto.randomUUID();
  const name = cleanName(nickname);
  await env.DB.prepare(
    `INSERT INTO participants (id, room_code, name, last_seen)
     VALUES (?, ?, ?, ?)
     ON CONFLICT(id) DO UPDATE SET room_code = excluded.room_code, name = excluded.name, last_seen = excluded.last_seen`,
  ).bind(id, code, name, Date.now()).run();
  return { id, name };
}

async function roomPayload(env, room) {
  return {
    code: room.code,
    state: JSON.parse(room.state_json),
    version: Number(room.version),
    finalized: Boolean(room.finalized),
    hostParticipantId: room.host_participant_id || null,
    participants: await activeParticipants(env, room.code),
    updatedAt: Number(room.updated_at),
  };
}

async function createRoom(request, env) {
  const body = await readBody(request);
  const participantId = String(body.participantId || crypto.randomUUID()).slice(0, 80);
  const nickname = cleanName(body.nickname, '房主');
  const state = cleanBoardState(body.state);
  const hostKey = crypto.randomUUID() + crypto.randomUUID();
  const now = Date.now();

  for (let attempt = 0; attempt < 12; attempt += 1) {
    const code = randomRoomCode();
    try {
      await env.DB.prepare(
        `INSERT INTO rooms (code, host_key, host_participant_id, state_json, version, finalized, created_at, updated_at)
         VALUES (?, ?, ?, ?, 0, 0, ?, ?)`,
      ).bind(code, hostKey, participantId, JSON.stringify(state), now, now).run();
      await touchParticipant(env, code, participantId, nickname);
      const room = await getRoom(env, code);
      return json({ ...(await roomPayload(env, room)), hostKey, participantId });
    } catch (error) {
      if (!String(error).toLowerCase().includes('unique')) throw error;
    }
  }
  return json({ error: '暂时无法生成房间号，请重试' }, 503);
}

async function joinRoom(request, env, code) {
  const room = await getRoom(env, code);
  if (!room) return json({ error: '房间不存在或已失效' }, 404);
  const body = await readBody(request);
  const participant = await touchParticipant(env, code, body.participantId, body.nickname);
  return json({ ...(await roomPayload(env, room)), participantId: participant.id });
}

async function readRoomState(env, code, url) {
  const room = await getRoom(env, code);
  if (!room) return json({ error: '房间不存在或已失效' }, 404);
  const version = Number(room.version);
  const sinceValue = url.searchParams.get('since');
  const since = sinceValue === null ? Number.NaN : Number(sinceValue);
  const payload = {
    code: room.code,
    version,
    finalized: Boolean(room.finalized),
    hostParticipantId: room.host_participant_id || null,
    participants: await activeParticipants(env, room.code),
    updatedAt: Number(room.updated_at),
  };
  if (!Number.isInteger(since) || since !== version) payload.state = JSON.parse(room.state_json);
  return json(payload);
}

async function transferRoom(request, env, code) {
  const body = await readBody(request);
  const room = await env.DB.prepare(
    'SELECT host_key, host_participant_id FROM rooms WHERE code = ?',
  ).bind(code).first();
  if (!room) return json({ error: '房间不存在或已失效' }, 404);
  if (!body.hostKey || body.hostKey !== room.host_key) return json({ error: '只有房主可以转让房间' }, 403);
  const targetParticipantId = String(body.targetParticipantId || '').slice(0, 80);
  if (!targetParticipantId || targetParticipantId === room.host_participant_id) {
    return json({ error: '请选择其他参与者接任房主' }, 400);
  }
  const target = await env.DB.prepare(
    'SELECT id FROM participants WHERE id = ? AND room_code = ? AND last_seen >= ?',
  ).bind(targetParticipantId, code, Date.now() - 30000).first();
  if (!target) return json({ error: '接任者已不在房间，请重新选择' }, 404);
  const nextHostKey = crypto.randomUUID() + crypto.randomUUID();
  await env.DB.prepare(
    'UPDATE rooms SET host_key = ?, host_participant_id = ?, updated_at = ? WHERE code = ?',
  ).bind(nextHostKey, targetParticipantId, Date.now(), code).run();
  if (room.host_participant_id) {
    await env.DB.prepare('DELETE FROM participants WHERE id = ? AND room_code = ?')
      .bind(room.host_participant_id, code).run();
  }
  const latest = await getRoom(env, code);
  return json({ ...(await roomPayload(env, latest)), transferred: true });
}

async function claimRoomHost(request, env, code) {
  const body = await readBody(request);
  const participantId = String(body.participantId || '').slice(0, 80);
  const room = await env.DB.prepare(
    'SELECT host_key, host_participant_id FROM rooms WHERE code = ?',
  ).bind(code).first();
  if (!room) return json({ error: '房间不存在或已失效' }, 404);
  if (!participantId || participantId !== room.host_participant_id) return json({ error: '当前参与者不是房主' }, 403);
  return json({ hostKey: room.host_key, hostParticipantId: room.host_participant_id });
}

async function dissolveRoom(request, env, code) {
  const body = await readBody(request);
  const room = await env.DB.prepare('SELECT host_key FROM rooms WHERE code = ?').bind(code).first();
  if (!room) return json({ error: '房间不存在或已失效' }, 404);
  if (!body.hostKey || body.hostKey !== room.host_key) return json({ error: '只有房主可以解散房间' }, 403);
  const images = await env.DB.prepare('SELECT object_key FROM room_images WHERE room_code = ?').bind(code).all();
  await Promise.all((images.results || []).map(image => env.FILES.delete(image.object_key)));
  await env.DB.prepare('DELETE FROM rooms WHERE code = ?').bind(code).run();
  return json({ dissolved: true, code });
}

async function presence(request, env, code) {
  const room = await getRoom(env, code);
  if (!room) return json({ error: '房间不存在或已失效' }, 404);
  const body = await readBody(request);
  await touchParticipant(env, code, body.participantId, body.nickname);
  const latest = await getRoom(env, code);
  return json(await roomPayload(env, latest));
}

async function syncRoom(request, env, code) {
  const body = await readBody(request);
  const room = await getRoom(env, code);
  if (!room) return json({ error: '房间不存在或已失效' }, 404);
  await touchParticipant(env, code, body.participantId, body.nickname);
  if (room.finalized) return json({ error: '最终排名已锁定', ...(await roomPayload(env, room)) }, 423);

  const baseVersion = Number(body.baseVersion);
  if (!Number.isInteger(baseVersion) || baseVersion !== Number(room.version)) {
    return json({ error: '房间已有新调整', ...(await roomPayload(env, room)) }, 409);
  }

  const nextState = cleanBoardState(body.state);
  const result = await env.DB.prepare(
    `UPDATE rooms SET state_json = ?, version = version + 1, updated_at = ?
     WHERE code = ? AND version = ? AND finalized = 0`,
  ).bind(JSON.stringify(nextState), Date.now(), code, baseVersion).run();

  if (!result.meta?.changes) {
    const latest = await getRoom(env, code);
    return json({ error: '房间已有新调整', ...(await roomPayload(env, latest)) }, 409);
  }
  const latest = await getRoom(env, code);
  return json(await roomPayload(env, latest));
}

async function finalizeRoom(request, env, code) {
  const body = await readBody(request);
  const room = await env.DB.prepare('SELECT host_key FROM rooms WHERE code = ?').bind(code).first();
  if (!room) return json({ error: '房间不存在或已失效' }, 404);
  if (!body.hostKey || body.hostKey !== room.host_key) return json({ error: '只有房主可以定稿' }, 403);
  await env.DB.prepare(
    'UPDATE rooms SET finalized = ?, version = version + 1, updated_at = ? WHERE code = ?',
  ).bind(body.finalized ? 1 : 0, Date.now(), code).run();
  const latest = await getRoom(env, code);
  return json(await roomPayload(env, latest));
}

async function uploadImage(request, env, code) {
  const room = await getRoom(env, code);
  if (!room) return json({ error: '房间不存在或已失效' }, 404);
  if (room.finalized) return json({ error: '最终排名已锁定' }, 423);
  const contentType = (request.headers.get('content-type') || '').split(';')[0].toLowerCase();
  if (!IMAGE_TYPES.has(contentType)) return json({ error: '仅支持 PNG、JPEG、WebP 和 GIF' }, 415);
  const bytes = await request.arrayBuffer();
  if (!bytes.byteLength || bytes.byteLength > MAX_IMAGE_BYTES) return json({ error: '单张图片不能超过 8MB' }, 413);

  const id = crypto.randomUUID();
  const extension = { 'image/png': 'png', 'image/jpeg': 'jpg', 'image/webp': 'webp', 'image/gif': 'gif' }[contentType];
  const objectKey = `rooms/${code}/${id}.${extension}`;
  let fileName = '图片';
  try { fileName = decodeURIComponent(request.headers.get('x-file-name') || '图片'); } catch (_) {}
  fileName = cleanName(fileName, '图片').slice(0, 120);
  await env.FILES.put(objectKey, bytes, { httpMetadata: { contentType } });
  await env.DB.prepare(
    `INSERT INTO room_images (id, room_code, object_key, file_name, content_type, size, created_at)
     VALUES (?, ?, ?, ?, ?, ?, ?)`,
  ).bind(id, code, objectKey, fileName, contentType, bytes.byteLength, Date.now()).run();
  return json({ id, name: fileName, url: `/api/images/${code}/${id}` }, 201);
}

async function serveImage(env, code, id) {
  if (!ROOM_CODE_PATTERN.test(code) || !id) return new Response('Not found', { status: 404 });
  const meta = await env.DB.prepare(
    'SELECT object_key, content_type FROM room_images WHERE id = ? AND room_code = ?',
  ).bind(id, code).first();
  if (!meta) return new Response('Not found', { status: 404 });
  const object = await env.FILES.get(meta.object_key);
  if (!object) return new Response('Not found', { status: 404 });
  return new Response(object.body, {
    headers: {
      'content-type': meta.content_type,
      'cache-control': 'public, max-age=31536000, immutable',
      'x-content-type-options': 'nosniff',
    },
  });
}

async function handleApi(request, env, url) {
  const parts = url.pathname.split('/').filter(Boolean);
  if (parts[0] !== 'api') return null;

  if (parts[1] === 'images' && parts.length === 4 && request.method === 'GET') {
    return serveImage(env, parts[2], parts[3]);
  }
  if (parts[1] !== 'rooms') return json({ error: '接口不存在' }, 404);
  if (parts.length === 2 && request.method === 'POST') return createRoom(request, env);

  const code = cleanRoomCode(parts[2]);
  if (!code) return json({ error: '房间号应为 8 位字母或数字' }, 400);
  if (parts.length === 3 && request.method === 'GET') return readRoomState(env, code, url);
  if (parts[3] === 'join' && request.method === 'POST') return joinRoom(request, env, code);
  if (parts[3] === 'presence' && request.method === 'POST') return presence(request, env, code);
  if (parts[3] === 'sync' && request.method === 'PUT') return syncRoom(request, env, code);
  if (parts[3] === 'finalize' && request.method === 'POST') return finalizeRoom(request, env, code);
  if (parts[3] === 'transfer' && request.method === 'POST') return transferRoom(request, env, code);
  if (parts[3] === 'claim-host' && request.method === 'POST') return claimRoomHost(request, env, code);
  if (parts[3] === 'dissolve' && request.method === 'POST') return dissolveRoom(request, env, code);
  if (parts[3] === 'images' && request.method === 'POST') return uploadImage(request, env, code);
  return json({ error: '接口不存在' }, 404);
}

export default {
  async fetch(request, env) {
    try {
      const url = new URL(request.url);
      const apiResponse = await handleApi(request, env, url);
      if (apiResponse) return apiResponse;
      if (request.method === 'GET' && (url.pathname === '/' || url.pathname === '/index.html')) {
        return new Response(INDEX_HTML, {
          headers: {
            'content-type': 'text/html; charset=utf-8',
            'cache-control': 'no-cache',
            'x-content-type-options': 'nosniff',
            'referrer-policy': 'same-origin',
          },
        });
      }
      return new Response('Not found', { status: 404 });
    } catch (error) {
      console.error(error);
      return json({ error: error instanceof Error ? error.message : '服务器暂时不可用' }, 500);
    }
  },
};
